snippets:
[
    // ============================================================
    // 1. 数学模式
    // ============================================================
    // 行内数学：mk
    {trigger: "mk", replacement: "$$0$", options: "tA"},
    // 块级数学：dm
    {trigger: "dm", replacement: "$$$0$$", options: "tAw"},

    // ============================================================
    // 2. 破折号（默认关闭，需要时取消注释）
    // ============================================================
    // {trigger: "--", replacement: "–", options: "tA"},
    // {trigger: "–-", replacement: "—", options: "tA"},
    // {trigger: "—-", replacement: "---", options: "tA"},

    // ============================================================
    // 3. 希腊字母
    // ============================================================
    {trigger: "@a", replacement: "\\alpha ", options: "mA"},
    {trigger: "@b", replacement: "\\beta ", options: "mA"},
    {trigger: "@g", replacement: "\\gamma ", options: "mA"},
    {trigger: "@G", replacement: "\\Gamma ", options: "mA"},
    {trigger: "@d", replacement: "\\delta ", options: "mA"},
    {trigger: "@D", replacement: "\\Delta ", options: "mA"},
    {trigger: "@e", replacement: "\\epsilon ", options: "mA"},
    {trigger: ":e", replacement: "\\varepsilon ", options: "mA"},
    {trigger: "@z", replacement: "\\zeta ", options: "mA"},
    {trigger: "@t", replacement: "\\theta ", options: "mA"},
    {trigger: "@T", replacement: "\\Theta ", options: "mA"},
    {trigger: ":t", replacement: "\\vartheta ", options: "mA"},
    {trigger: "@i", replacement: "\\iota ", options: "mA"},
    {trigger: "@k", replacement: "\\kappa ", options: "mA"},
    {trigger: "@l", replacement: "\\lambda ", options: "mA"},
    {trigger: "@L", replacement: "\\Lambda ", options: "mA"},
    {trigger: "@s", replacement: "\\sigma ", options: "mA"},
    {trigger: "@S", replacement: "\\Sigma ", options: "mA"},
    {trigger: "@u", replacement: "\\upsilon ", options: "mA"},
    {trigger: "@U", replacement: "\\Upsilon ", options: "mA"},
    {trigger: "@o", replacement: "\\omega ", options: "mA"},
    {trigger: "@O", replacement: "\\Omega ", options: "mA"},
    {trigger: "@m", replacement: "\\mu", options: "mA"},
    {trigger: "ome", replacement: "\\omega ", options: "mA"},
    {trigger: "Ome ", replacement: "\\Omega", options: "mA"},

    // ============================================================
    // 4. 文本环境
    // ============================================================
    {trigger: "text", replacement: "\\text{$0}$1", options: "mA"},
    {trigger: "\"", replacement: "\\text{$0}$1", options: "mA"},

    // ============================================================
    // 5. 基础运算与结构
    // ============================================================
    {trigger: "sr", replacement: "^{2} ", options: "mA"},
    {trigger: "cb", replacement: "^{3} ", options: "mA"},
    {trigger: "rd", replacement: "^{ $0 } $1", options: "mA"},
    {trigger: "_", replacement: "_{ $0 } $1", options: "mA"},
    {trigger: "^", replacement: "^{ $0 } $1", options: "mA"},
    {trigger: "sts", replacement: "_\\text{ $0 }", options: "mA"},
    {trigger: "sq", replacement: "\\sqrt{ $0 } $1", options: "mA"},
    {trigger: "//", replacement: "\\frac{ $0 }{ $1 } $2", options: "mA"},
    {trigger: "exx", replacement: "e^{ $0 } $1", options: "mA"},
    {trigger: "invs", replacement: "^{-1} ", options: "mA"},

    // 自动字母下标：如 x1 -> x_{1}
    {trigger: /([A-Za-z])(\d)/, replacement: "[[0]]_{[[1]]}", options: "rmA", description: "Auto letter subscript", priority: -1},

    // 环境
    {trigger: "beg", replacement: "\\begin{$0}\n$1\n\\end{$0}", options: "mA"},

    // ============================================================
    // 6. 常用函数与字体
    // ============================================================
    {trigger: /([^\\])(exp|log|ln)/, replacement: "[[0]]\\[[1]]", options: "rmA"},
    {trigger: "conj", replacement: "^{*} ", options: "mA"},
    {trigger: "dd", replacement: "\\mathrm{d} ", options: "mA"},
    {trigger: "Re", replacement: "\\mathrm{Re} ", options: "mA"},
    {trigger: "Im", replacement: "\\mathrm{Im} ", options: "mA"},
    {trigger: "bf", replacement: "\\mathbf{$0} $1", options: "mA"},
    {trigger: "rm", replacement: "\\mathrm{$0} $1", options: "mA"},

    // ============================================================
    // 7. 线性代数
    // ============================================================
    {trigger: /([^\\])(det)/, replacement: "[[0]]\\[[1]]", options: "rmA"},
    {trigger: "trace", replacement: "\\mathrm{Tr} ", options: "mA"},

    // ============================================================
    // 8. 帽子、横线、点、向量等修饰
    // ============================================================
    {trigger: "([a-zA-Z])hat", replacement: "\\hat{[[0]]}", options: "rmA"},
    {trigger: "([a-zA-Z])bar", replacement: "\\bar{[[0]]}", options: "rmA"},
    {trigger: "([a-zA-Z])dot", replacement: "\\dot{[[0]]}", options: "rmA", priority: -1},
    {trigger: "([a-zA-Z])ddot", replacement: "\\ddot{[[0]]}", options: "rmA", priority: 1},
    {trigger: "([a-zA-Z])tilde", replacement: "\\tilde{[[0]]}", options: "rmA"},
    {trigger: "([a-zA-Z])und", replacement: "\\underline{[[0]]}", options: "rmA"},
    {trigger: "([a-zA-Z])vec", replacement: "\\vec{[[0]]}", options: "rmA"},
    {trigger: "([a-zA-Z]),\\.", replacement: "\\mathbf{[[0]]}", options: "rmA"},
    {trigger: "([a-zA-Z])\\.,", replacement: "\\mathbf{[[0]]}", options: "rmA"},
    {trigger: "\\\\(${GREEK}),\\.", replacement: "\\boldsymbol{\\[[0]]}", options: "rmA"},
    {trigger: "\\\\(${GREEK})\\.,", replacement: "\\boldsymbol{\\[[0]]}", options: "rmA"},

    {trigger: "hat", replacement: "\\hat{$0} $1", options: "mA"},
    {trigger: "bar", replacement: "\\bar{$0} $1", options: "mA"},
    {trigger: "dot", replacement: "\\dot{$0} $1", options: "mA", priority: -1},
    {trigger: "ddot", replacement: "\\ddot{$0} $1", options: "mA"},
    {trigger: "cdot", replacement: "\\cdot ", options: "mA"},
    {trigger: "tilde", replacement: "\\tilde{$0} $1", options: "mA"},
    {trigger: "und", replacement: "\\underline{$0} $1", options: "mA"},
    {trigger: "vec", replacement: "\\vec{$0} $1", options: "mA"},

    // 模运算：pmod
    {
        trigger: "pmod",
        replacement: "\\pmod{${0:n}} $1",
        options: "mA",
        description: "Parenthesized modulo (\\pmod{n})",
    },

    // ============================================================
    // 9. 更多自动下标
    // ============================================================
    {trigger: /([A-Za-z])_(\d\d)/, replacement: "[[0]]_{[[1]]}", options: "rmA"},
    {trigger: /\\hat{([A-Za-z])}(\d)/, replacement: "\\hat{[[0]]}_{[[1]]}", options: "rmA"},
    {trigger: /\\vec{([A-Za-z])}(\d)/, replacement: "\\vec{[[0]]}_{[[1]]}", options: "rmA"},
    {trigger: /\\mathbf{([A-Za-z])}(\d)/, replacement: "\\mathbf{[[0]]}_{[[1]]}", options: "rmA"},

    {trigger: "xnn", replacement: "x_{n} ", options: "mA"},
    {trigger: "\\xii", replacement: "x_{i} ", options: "mA", priority: 1},
    {trigger: "xjj", replacement: "x_{j} ", options: "mA"},
    {trigger: "xp1", replacement: "x_{n+1} ", options: "mA"},
    {trigger: "ynn", replacement: "y_{n} ", options: "mA"},
    {trigger: "yii", replacement: "y_{i} ", options: "mA"},
    {trigger: "yjj", replacement: "y_{j} ", options: "mA"},

    // ============================================================
    // 10. 常用符号
    // ============================================================
    {trigger: "ooo", replacement: "\\infty ", options: "mA"},
    {trigger: "sum", replacement: "\\sum ", options: "mA"},
    {trigger: "prod", replacement: "\\prod ", options: "mA"},
    {trigger: "\\sum", replacement: "\\sum_{${0:i}=${1:1}}^{${2:N}} $3", options: "m"},
    {trigger: "\\prod", replacement: "\\prod_{${0:i}=${1:1}}^{${2:N}} $3", options: "m"},
    {trigger: "lim", replacement: "\\lim_{ ${0:n} \\to ${1:\\infty} } $2", options: "mA"},
    {trigger: "+-", replacement: "\\pm ", options: "mA"},
    {trigger: "-+", replacement: "\\mp ", options: "mA"},
    {trigger: "...", replacement: "\\dots ", options: "mA"},
    {trigger: "nabl", replacement: "\\nabla ", options: "mA"},

    // 注意：nabla 也叫 del，但 del 与 delta 冲突，故默认关闭
    // {trigger: "del", replacement: "\\nabla", options: "mA"},

    {trigger: "xx", replacement: "\\times ", options: "mA"},
    {trigger: "**", replacement: "\\cdot ", options: "mA"},
    {trigger: "para", replacement: "\\parallel ", options: "mA"},

    // 关系符
    {trigger: "===", replacement: "\\equiv ", options: "mA"},
    {trigger: "!=", replacement: "\\neq ", options: "mA"},
    {trigger: "neq", replacement: "\\neq ", options: "mA"},
    {trigger: ">=", replacement: "\\geq ", options: "mA"},
    {trigger: "geq", replacement: "\\geq ", options: "mA"},
    {trigger: "<=", replacement: "\\leq ", options: "mA"},
    {trigger: "leq", replacement: "\\leq ", options: "mA"},
    {trigger: ">>", replacement: "\\gg ", options: "mA"},
    {trigger: "gg", replacement: "\\gg ", options: "mA"},
    {trigger: "<<", replacement: "\\ll ", options: "mA"},
    {trigger: "ll", replacement: "\\ll ", options: "mA"},
    {trigger: "simm", replacement: "\\sim ", options: "mA"},
    {trigger: "sim=", replacement: "\\simeq ", options: "mA"},
    {trigger: "prop", replacement: "\\propto ", options: "mA"},

    // 箭头
    {trigger: "<->", replacement: "\\leftrightarrow ", options: "mA"},
    {trigger: "->", replacement: "\\to ", options: "mA"},
    {trigger: "!>", replacement: "\\mapsto ", options: "mA"},
    {trigger: "=>", replacement: "\\implies ", options: "mA"},
    {trigger: "=<", replacement: "\\impliedby ", options: "mA"},

    // 集合与逻辑
    {trigger: "and", replacement: "\\cap ", options: "mA"},
    {trigger: "orr", replacement: "\\cup ", options: "mA"},
    {trigger: "inn", replacement: "\\in ", options: "mA"},
    {trigger: "notin", replacement: "\\not\ \\in ", options: "mA"},
    {trigger: "\\\\\\", replacement: "\\setminus ", options: "mA"},
    {trigger: "sub=", replacement: "\\subseteq ", options: "mA"},
    {trigger: "sup=", replacement: "\\supseteq ", options: "mA"},
    {trigger: "eset", replacement: "\\emptyset ", options: "mA"},
    {trigger: "set", replacement: "\\{ $0 \\}$1", options: "mA"},
    {trigger: "Exi", replacement: "\\exists ", options: "mA", priority: 1},
    {trigger: "All", replacement: "\\forall ", options: "mA", priority: 1},

    // 常用数学字母
    {trigger: "LL", replacement: "\\mathcal{L} ", options: "mA"},
    {trigger: "HH", replacement: "\\mathcal{H} ", options: "mA"},
    {trigger: "CC", replacement: "\\mathbb{C} ", options: "mA"},
    {trigger: "EE", replacement: "\\mathcal{E} ", options: "mA"},
    {trigger: "Ee", replacement: "\\mathscr{E} ", options: "mA"},
    {trigger: "RR", replacement: "\\mathbb{R} ", options: "mA"},
    {trigger: "ZZ", replacement: "\\mathbb{Z} ", options: "mA"},
    {trigger: "NN", replacement: "\\mathbb{N} ", options: "mA"},

    // ============================================================
    // 11. 自动补反斜杠与空格处理
    // ============================================================
    // 说明：${GREEK}、${SYMBOL}、${MORE_SYMBOLS} 是 Latex Suite 片段变量，
    // 可在 Advanced snippet settings 中编辑。
    {trigger: "([^\\\\])(${GREEK})", replacement: "[[0]]\\[[1]]", options: "rmA", description: "Add backslash before Greek letters"},
    {trigger: "([^\\\\])(${SYMBOL})", replacement: "[[0]]\\[[1]]", options: "rmA", description: "Add backslash before symbols"},

    // 在希腊字母和符号后插入空格
    {trigger: "\\\\(${GREEK}|${SYMBOL}|${MORE_SYMBOLS})([A-Za-z])", replacement: "\\[[0]] [[1]]", options: "rmA"},
    {trigger: "\\\\(${GREEK}|${SYMBOL}) sr", replacement: "\\[[0]]^{2} ", options: "rmA"},
    {trigger: "\\\\(${GREEK}|${SYMBOL}) cb", replacement: "\\[[0]]^{3} ", options: "rmA"},
    {trigger: "\\\\(${GREEK}|${SYMBOL}) rd", replacement: "\\[[0]]^{$0} $1", options: "rmA"},
    {trigger: "\\\\(${GREEK}) hat", replacement: "\\hat{\\[[0]]} ", options: "rmA"},
    {trigger: "\\\\(${GREEK}) dot", replacement: "\\dot{\\[[0]]} ", options: "rmA"},
    {trigger: "\\\\(${GREEK}) bar", replacement: "\\bar{\\[[0]]} ", options: "rmA"},
    {trigger: "\\\\(${GREEK}) vec", replacement: "\\vec{\\[[0]]} ", options: "rmA"},
    {trigger: "\\\\(${GREEK}) tilde", replacement: "\\tilde{\\[[0]]} ", options: "rmA"},
    {trigger: "\\\\(${GREEK}) und", replacement: "\\underline{\\[[0]]} ", options: "rmA"},

    // ============================================================
    // 12. 导数与积分
    // ============================================================
    {trigger: "par", replacement: "\\frac{ \\partial ${0:y} }{ \\partial ${1:x} } $2", options: "m"},
    {trigger: /pa([A-Za-z])([A-Za-z])/, replacement: "\\frac{ \\partial [[0]] }{ \\partial [[1]] } ", options: "rm"},
    {trigger: "dtt", replacement: "\\frac{d}{dt} ", options: "mA"},

    {trigger: /([^\\])int/, replacement: "[[0]]\\int ", options: "mA", priority: -1},
    {trigger: "\\int", replacement: "\\int $0 \\, d${1:x} $2", options: "m"},
    {trigger: "dint", replacement: "\\int_{${0:0}}^{${1:1}} $2 \\, d${3:x} $4", options: "mA"},
    {trigger: "oint", replacement: "\\oint ", options: "mA"},
    {trigger: "iint", replacement: "\\iint ", options: "mA"},
    {trigger: "iiint", replacement: "\\iiint ", options: "mA"},
    {trigger: "oinf", replacement: "\\int_{0}^{\\infty} $0 \\, d${1:x} $2", options: "mA"},
    {trigger: "infi", replacement: "\\int_{-\\infty}^{\\infty} $0 \\, d${1:x} $2", options: "mA"},

    // ============================================================
    // 13. 三角函数
    // ============================================================
    {trigger: /([^\\])(arcsin|sin|arccos|cos|arctan|tan|csc|sec|cot)/, replacement: "[[0]]\\[[1]]", options: "rmA", description: "Add backslash before trig funcs"},

    {
        trigger: /\\(arcsin|sin|arccos|cos|arctan|tan|csc|sec|cot)([A-Za-gi-z])/,
        replacement: "\\[[0]] [[1]]",
        options: "rmA",
        description: "Add space after trig funcs. Skips letter h to allow sinh, cosh, etc."
    },

    {
        trigger: /\\(sinh|cosh|tanh|coth)([A-Za-z])/,
        replacement: "\\[[0]] [[1]]",
        options: "rmA",
        description: "Add space after hyperbolic trig funcs"
    },

    {
        trigger: /(arccsc|arcsec|arccot)/,
        replacement: "\\operatorname{[[0]]}$0",
        options: "mA",
        description: "Inverse trig functions, Are not built-in MathJax functions",
        priority: 1,
    },

    // ============================================================
    // 14. 可视化操作（选中 VISUAL 后触发）
    // ============================================================
    {trigger: "U", replacement: "\\underbrace{ ${VISUAL} }_{ $0 }", options: "mA"},
    {trigger: "O", replacement: "\\overbrace{ ${VISUAL} }^{ $0 }", options: "mA"},
    {trigger: "B", replacement: "\\underset{ $0 }{ ${VISUAL} }", options: "mA"},
    {trigger: "C", replacement: "\\cancel{ ${VISUAL} }", options: "mA"},
    {trigger: "K", replacement: "\\cancelto{ $0 }{ ${VISUAL} }", options: "mA"},
    {trigger: "S", replacement: "\\sqrt{ ${VISUAL} }", options: "mA"},

    // ============================================================
    // 15. 物理
    // ============================================================
    {trigger: "kbt", replacement: "k_{B}T", options: "mA"},
    {trigger: "msun", replacement: "M_{\\odot}", options: "mA"},

    // ============================================================
    // 16. 量子力学
    // ============================================================
    {trigger: "dag", replacement: "^{\\dagger}", options: "mA"},
    {trigger: "o+", replacement: "\\oplus ", options: "mA"},
    {trigger: "ox", replacement: "\\otimes ", options: "mA"},
    {trigger: "bra", replacement: "\\bra{$0} $1", options: "mA"},
    {trigger: "ket", replacement: "\\ket{$0} $1", options: "mA"},
    {trigger: "brk", replacement: "\\braket{ $0 | $1 } $2", options: "mA"},
    {trigger: "outer", replacement: "\\ket{${0:\\psi}} \\bra{${0:\\psi}} $1", options: "mA"},

    // ============================================================
    // 17. 化学
    // ============================================================
    {trigger: "pu", replacement: "\\pu{ $0 }", options: "mA"},
    {trigger: "cee", replacement: "\\ce{ $0 }", options: "mA"},
    {trigger: "he4", replacement: "{}^{4}_{2}He ", options: "mA"},
    {trigger: "he3", replacement: "{}^{3}_{2}He ", options: "mA"},
    {trigger: "iso", replacement: "{}^{${0:4}}_{${1:2}}${2:He}", options: "mA"},

    // ============================================================
    // 18. 矩阵与常用环境
    // ============================================================
    // 矩阵环境：pmat/bmat/Bmat/vmat/Vmat，带换行
    {
        trigger: /([pbBvV]mat)/,
        replacement: "\\begin{[[0]]rix}\n$0\n\\end{[[0]]rix}",
        options: "rMA",
        description: "Matrix environments with new lines",
    },

    // 其他环境：matrix/cases/align/array，带换行
    {
        trigger: /(matrix|cases|align|array)/,
        replacement: "\\begin{[[0]]}\n$0\n\\end{[[0]]}",
        options: "rMA",
        description: "Miscellaneous environments with new lines",
    },

    // 矩阵环境：不带换行
    {
        trigger: /([pbBvV]mat)/,
        replacement: "\\begin{[[0]]rix}$0\\end{[[0]]rix}",
        options: "rnA",
    },

    // 其他环境：不带换行
    {
        trigger: /(matrix|cases|align|array)/,
        replacement: "\\begin{[[0]]}$0\\end{[[0]]}",
        options: "rnA",
    },

    // ============================================================
    // 19. 括号、范数、取整等
    // ============================================================
    {trigger: "avg", replacement: "\\langle $0 \\rangle $1", options: "mA"},
    {trigger: "norm", replacement: "\\lvert $0 \\rvert $1", options: "mA", priority: 1},
    {trigger: "Norm", replacement: "\\lVert $0 \\rVert $1", options: "mA", priority: 1},
    {trigger: "ceil", replacement: "\\lceil $0 \\rceil $1", options: "mA"},
    {trigger: "floor", replacement: "\\lfloor $0 \\rfloor $1", options: "mA"},
    {trigger: "mod", replacement: "|$0|$1", options: "mA"},

    // 选中内容后包裹
    {trigger: "(", replacement: "(${VISUAL})", options: "mA"},
    {trigger: "[", replacement: "[${VISUAL}]", options: "mA"},
    {trigger: "{", replacement: "{${VISUAL}}", options: "mA"},

    // 普通插入括号
    {trigger: "(", replacement: "($0)$1", options: "mA"},
    {trigger: "{", replacement: "{$0}$1", options: "mA"},
    {trigger: "[", replacement: "[$0]$1", options: "mA"},

    // 自适应大小括号
    {trigger: "lr(", replacement: "\\left( $0 \\right) $1", options: "mA"},
    {trigger: "lr{", replacement: "\\left\\{ $0 \\right\\} $1", options: "mA"},
    {trigger: "lr[", replacement: "\\left[ $0 \\right] $1", options: "mA"},
    {trigger: "lr|", replacement: "\\left| $0 \\right| $1", options: "mA"},
    {trigger: "lra", replacement: "\\left< $0 \\right> $1", options: "mA"},

    // ============================================================
    // 20. 杂项自动转换（默认关闭，需要时取消注释）
    // ============================================================
    // 自动将文本中的独立字母转成数学模式，但排除 a、A、I。
    // {trigger: /([^'])\b([B-HJ-Zb-z])\b([\n\s.,?!:'])/, replacement: "[[0]]$[[1]]$[[2]]", options: "tA"},

    // 自动将文本中的希腊字母转成数学模式。
    // {trigger: "(${GREEK})([\\n\\s.,?!:'])", replacement: "$\\[[0]]$[[1]]", options: "rtAw"},

    // 自动将 x=2 这类文本转成数学模式。
    // {trigger: /([A-Za-z]=\d+)([\n\s.,?!:'])/, replacement: "$[[0]]$[[1]]", options: "rtAw"},
    // {trigger: /([A-Za-z]=[A-Za-z][+-]\d+)([\n\s.,?!:'])/, replacement: "$[[0]]$[[1]]", options: "tAw"},

    // ============================================================
    // 21. 泰勒展开
    // ============================================================
    {
        trigger: "tayl",
        replacement: "${0:f}(${1:x} + ${2:h}) = ${0:f}(${1:x}) + ${0:f}'(${1:x})${2:h} + ${0:f}''(${1:x}) \\frac{${2:h}^{2}}{2!} + \\dots$3",
        options: "mA",
        description: "Taylor expansion"
    },

    // ============================================================
    // 22. JavaScript 动态片段：n 阶单位矩阵
    // ============================================================
    {
        trigger: /iden(\d)/,
        replacement: (match) => {
            const n = match[1];

            let arr = [];
            for (let j = 0; j < n; j++) {
                arr[j] = [];
                for (let i = 0; i < n; i++) {
                    arr[j][i] = (i === j) ? 1 : 0;
                }
            }

            let output = arr.map(el => el.join(" & ")).join(" \\\\\n");
            output = `\\begin{pmatrix}\n${output}\n\\end{pmatrix}`;
            return output;
        },
        options: "mA",
        description: "N x N identity matrix"
    },
]
